//! The small committed fixtures of the whole-output invariant gate (#779, G3),
//! each through convert + export, asserting the property its bug broke.
//!
//! The fixtures live in `tests/fixtures/invariants/` and are generated by
//! `uv run crates/core/tests/fixtures/invariants/make_fixtures.py` (see its
//! docstring for what each one is). A case that fails on the current tree
//! is a strict expected failure: the assertion is `#[ignore = "#NNN …"]`,
//! and a sibling test asserts the bug is still there, so the fix has to
//! delete both — an ignore can never outlive its bug.
//!
//! The non-finite-vertex fixture (#707) has no test here: its failure is a
//! feature missing from the archive with no counter, which only decoding
//! every tile shows. It runs in the strict e2e matrix
//! (`benchmarks/e2e/run_e2e.py --invariants`, dataset `nonfinite-vertex`).

use std::path::{Path, PathBuf};

use tylertoo_core::overview::convert::{
    convert_to_overviews, ConvertOptions, ConvertReport, LevelPlan,
};
use tylertoo_core::overview::export::{export_pmtiles, ExportOptions, ExportReport};

#[path = "../../../tests/support/fixture.rs"]
mod fixture;

/// A committed fixture of this gate. Committed as plain blobs (not LFS), so
/// a missing one is a repo bug, not an environment gap.
fn invariant_fixture(name: &str) -> PathBuf {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/invariants")
        .join(name);
    assert!(
        path.is_file(),
        "missing committed fixture {}",
        path.display()
    );
    path
}

/// Convert `input` over `min..=max` zooms and export it; both reports.
fn tiles(
    input: &Path,
    min_zoom: u8,
    max_zoom: u8,
    convert: ConvertOptions,
    export: ExportOptions,
) -> (ConvertReport, ExportReport) {
    let dir = tempfile::tempdir().expect("tempdir");
    let overview = dir.path().join("ov.parquet");
    let archive = dir.path().join("out.pmtiles");
    let conv = convert_to_overviews(
        input,
        &overview,
        &ConvertOptions {
            levels: LevelPlan::ZoomRange { min_zoom, max_zoom },
            ..convert
        },
    )
    .unwrap_or_else(|e| panic!("convert {}: {e}", input.display()));
    let exp = export_pmtiles(&overview, &archive, &export)
        .unwrap_or_else(|e| panic!("export {}: {e}", input.display()));
    (conv, exp)
}

/// Per zoom: (zoom, tiles, features written).
fn per_zoom(report: &ExportReport) -> Vec<(u8, usize, usize)> {
    report
        .zooms
        .iter()
        .map(|z| (z.zoom, z.tile_count, z.tile_feature_count))
        .collect()
}

// --- #675: a geometry column not named `geometry` ---------------------------

/// open-buildings with its geometry column renamed `SHAPE` (the `geo` key
/// names it) tiles exactly like the original.
#[test]
fn shape_column_tiles_like_the_geometry_column() {
    let Some(original) = fixture::realdata("open-buildings.parquet") else {
        return;
    };
    let shape = invariant_fixture("shape-column.parquet");
    let (c0, e0) = tiles(
        &original,
        0,
        14,
        ConvertOptions::default(),
        ExportOptions::default(),
    );
    let (c1, e1) = tiles(
        &shape,
        0,
        14,
        ConvertOptions::default(),
        ExportOptions::default(),
    );
    assert_eq!(c1.input_features, c0.input_features);
    assert_eq!(
        per_zoom(&e1),
        per_zoom(&e0),
        "SHAPE tiles differently (#675)"
    );
    assert!(e1.total_tile_features > 0);
}

// --- #708: GeoParquet 2.0, native GEOMETRY type, no `geo` key ----------------

fn native_geoparquet2(streaming: bool) -> (ConvertReport, ExportReport) {
    tiles(
        &invariant_fixture("geoparquet2-native.parquet"),
        0,
        14,
        ConvertOptions {
            streaming,
            ..Default::default()
        },
        ExportOptions::default(),
    )
}

/// The native file declares its CRS through the logical type (an empty crs
/// is OGC:CRS84), so the report must not say WGS84 was assumed, and the
/// "no CRS declared … assuming WGS84" warning must not fire.
#[test]
fn native_geoparquet2_declares_its_crs() {
    for streaming in [true, false] {
        let (conv, exp) = native_geoparquet2(streaming);
        assert!(
            !conv.crs_assumed_wgs84,
            "#708: the logical type declares the CRS (streaming={streaming})"
        );
        assert!(exp.total_tile_features > 0);
    }
}

// --- #643: --bbox on data stored in 0..360 ----------------------------------

/// `lon-0-360.expected.json`: the bbox and how many features the export's
/// wrap rule puts inside it.
fn lon_0_360_expectation() -> ([f64; 4], usize) {
    let text = std::fs::read_to_string(invariant_fixture("lon-0-360.expected.json"))
        .expect("read lon-0-360.expected.json");
    let v: serde_json::Value = serde_json::from_str(&text).expect("parse expectation");
    let b: Vec<f64> = v["bbox"]
        .as_array()
        .expect("bbox")
        .iter()
        .map(|x| x.as_f64().expect("bbox number"))
        .collect();
    let n = v["expected_selected"].as_u64().expect("expected_selected") as usize;
    ([b[0], b[1], b[2], b[3]], n)
}

/// A `--bbox` in the -180..180 convention selects exactly the features the
/// export draws inside it, wrapped by ±360 (#342), on both engines.
#[test]
fn bbox_on_0_360_data_selects_the_wrapped_draw_count() {
    let (bbox, expected) = lon_0_360_expectation();
    assert!(expected > 0, "the fixture must put features in the box");
    for streaming in [true, false] {
        let (conv, exp) = tiles(
            &invariant_fixture("lon-0-360.parquet"),
            0,
            8,
            ConvertOptions {
                bbox: Some(bbox),
                streaming,
                ..Default::default()
            },
            ExportOptions::default(),
        );
        assert_eq!(
            conv.input_features, expected,
            "streaming={streaming}: --bbox {bbox:?} selected {} features, the wrap rule \
             draws {expected} there (#643)",
            conv.input_features
        );
        assert!(exp.total_tile_features > 0);
    }
}

// --- #768: banded, unsorted parcels through the merge valve ------------------

/// A compressed cap low enough that the merge valve works the middle zooms
/// of the 6,000-parcel fixture.
const BANDED_CAP: usize = 40 * 1024;
/// Per-zoom feature counts of the banded and the Hilbert-sorted copy may
/// differ by this share: row order may break ties, not change density.
const BANDED_TOLERANCE: f64 = 0.02;

/// Per-zoom (zoom, features) of the banded and the sorted copy.
fn banded_vs_sorted() -> Vec<(u8, usize, usize)> {
    let run = |name: &str| {
        tiles(
            &invariant_fixture(name),
            4,
            14,
            ConvertOptions::default(),
            ExportOptions {
                compressed_tile_size_limit: Some(BANDED_CAP),
                ..ExportOptions::default()
            },
        )
        .1
    };
    let banded = run("banded-parcels.parquet");
    let sorted = run("banded-parcels-sorted.parquet");
    assert!(
        sorted.merged_features > 0,
        "the cap must make the merge valve work, or this compares nothing"
    );
    per_zoom(&banded)
        .into_iter()
        .zip(per_zoom(&sorted))
        .map(|((z, _, b), (zs, _, s))| {
            assert_eq!(z, zs);
            (z, b, s)
        })
        .collect()
}

/// Zooms where the banded copy's feature count is off the sorted copy's by
/// more than [`BANDED_TOLERANCE`].
fn banded_steps(rows: &[(u8, usize, usize)]) -> Vec<String> {
    rows.iter()
        .filter(|(_, b, s)| (*b as f64 - *s as f64).abs() > BANDED_TOLERANCE * (*s as f64))
        .map(|(z, b, s)| format!("z{z}: banded {b} vs sorted {s}"))
        .collect()
}

/// The same parcels in banded or Hilbert order thin to the same density:
/// the merge valve's choices must not follow the input's row order.
#[test]
#[ignore = "#768: the merge valve merges by row order, so banded input keeps 10-13% fewer features at z7-z9 than the same rows Hilbert-sorted; C2 (valve design) removes this ignore and banded_parcels_still_thin_by_row_order_768"]
fn banded_parcels_thin_like_sorted_parcels() {
    let steps = banded_steps(&banded_vs_sorted());
    assert!(steps.is_empty(), "#768: {}", steps.join(", "));
}

/// The pin for the ignore above: passes while #768 is open.
#[test]
fn banded_parcels_still_thin_by_row_order_768() {
    let steps = banded_steps(&banded_vs_sorted());
    assert!(
        !steps.is_empty(),
        "#768 looks fixed: remove the #[ignore] on banded_parcels_thin_like_sorted_parcels \
         and delete this test"
    );
}
